\set ON_ERROR_STOP on
begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) values ('49100000-0000-4000-8000-000000000001','authenticated','authenticated','ka-sync@example.test','{}','{}');
insert into public.platform_operators(user_id) values ('49100000-0000-4000-8000-000000000001');
insert into public.workspaces(id,name) values ('49100000-0000-4000-8000-000000000011','KA Sync');
insert into public.workspace_members(workspace_id,user_id,role) values ('49100000-0000-4000-8000-000000000011','49100000-0000-4000-8000-000000000001','owner');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"49100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.ka.binding',public.kleinanzeigen_connect_account('49100000-0000-4000-8000-000000000011','123','Testkonto','private','49100000-0000-4000-8000-000000000031',repeat('a',64),false)::text,true);
reset role;
create function pg_temp.ka_connection() returns bigint language sql as $$ select (current_setting('test.ka.binding')::jsonb->>'connectionId')::bigint $$;
create function pg_temp.ka_request() returns jsonb language sql as $$ select public.kleinanzeigen_request_sync('49100000-0000-4000-8000-000000000011',pg_temp.ka_connection()) $$;
set local role authenticated;
select set_config('test.ka.first_run',pg_temp.ka_request()::text,true);
reset role;
select has_table('public','kleinanzeigen_sync_runs','Abgleichsläufe existieren getrennt vom bestätigten Bestand');
select has_table('public','kleinanzeigen_sync_entries','Unvollständige Seiten werden getrennt vorgemerkt');
select has_table('public','kleinanzeigen_publications','Eigene Kleinanzeigen-Lesekopie vorhanden');
insert into public.kleinanzeigen_publications(workspace_id,connection_id,external_id,title,url,state,observed_at)
select '49100000-0000-4000-8000-000000000011',pg_temp.ka_connection(),id,'Altbestand '||id,'https://www.kleinanzeigen.de/s-anzeige/test/'||id||'-160-1','active',now() from unnest(array['101','102','103']) id;
create function pg_temp.ka_claim(p_run text) returns jsonb language sql as $$ select public.kleinanzeigen_claim_sync('49100000-0000-4000-8000-000000000011',pg_temp.ka_connection(),repeat('a',64),1,(p_run::jsonb->>'runId')::bigint) $$;
create function pg_temp.ka_page(p_claim text,p_cursor text,p_next text,p_items jsonb,p_identity text default '123') returns jsonb language sql as $$ select public.kleinanzeigen_store_sync_page('49100000-0000-4000-8000-000000000011',pg_temp.ka_connection(),repeat('a',64),1,(p_claim::jsonb->>'runId')::bigint,p_claim::jsonb->>'claimToken',p_identity,p_cursor,p_next,p_items) $$;
create function pg_temp.ka_finish(p_claim text,p_identity text default '123',p_quota jsonb default null) returns jsonb language sql as $$ select public.kleinanzeigen_finish_sync('49100000-0000-4000-8000-000000000011',pg_temp.ka_connection(),repeat('a',64),1,(p_claim::jsonb->>'runId')::bigint,p_claim::jsonb->>'claimToken',p_identity,p_quota) $$;
set local role service_role;
select set_config('test.ka.first_claim',pg_temp.ka_claim(current_setting('test.ka.first_run'))::text,true);
select lives_ok($$select pg_temp.ka_page(current_setting('test.ka.first_claim'),'page:1','page:2','[{"externalId":"101","title":"Neu 101","url":"https://www.kleinanzeigen.de/s-anzeige/test/101-160-1","publishedAt":null,"state":"active"}]')$$,'Erste unvollständige Seite annehmbar');
select throws_ok($$select pg_temp.ka_finish(current_setting('test.ka.first_claim'))$$,'55000',null,'Unvollständige Cursorfolge nicht abschließbar');
reset role;
select is((select count(*)::int from public.kleinanzeigen_publications where available),3,'Abbruch nach Seite 1 bewahrt A/B/C');
select is((select title from public.kleinanzeigen_publications where external_id='101'),'Altbestand 101','Vorgemerkte Änderung ersetzt bestätigten Bestand nicht');
set local role service_role;
select lives_ok($$select public.kleinanzeigen_fail_sync('49100000-0000-4000-8000-000000000011',pg_temp.ka_connection(),repeat('a',64),1,(current_setting('test.ka.first_claim')::jsonb->>'runId')::bigint,current_setting('test.ka.first_claim')::jsonb->>'claimToken','123','interrupted')$$,'Unterbrochenen Lauf ausdrücklich abbrechen, Bestand erhalten');
reset role;
set local role authenticated;
select set_config('test.ka.second_run',pg_temp.ka_request()::text,true);
reset role;
set local role service_role;
select set_config('test.ka.second_claim',pg_temp.ka_claim(current_setting('test.ka.second_run'))::text,true);
select set_config('test.ka.page','[{"externalId":"101","title":"Neu 101","url":"https://www.kleinanzeigen.de/s-anzeige/test/101-160-1","publishedAt":null,"state":"active"},{"externalId":"102","title":"Neu 102","url":"https://www.kleinanzeigen.de/s-anzeige/test/102-160-1","publishedAt":null,"state":"unknown"}]',true);
select lives_ok($$select pg_temp.ka_page(current_setting('test.ka.second_claim'),'page:1',null,current_setting('test.ka.page')::jsonb)$$,'Vollständige Seite vormerkbar');
select lives_ok($$select pg_temp.ka_page(current_setting('test.ka.second_claim'),'page:1',null,current_setting('test.ka.page')::jsonb)$$,'Identische Seitenwiederholung ist idempotent');
select is((select count(*)::int from public.kleinanzeigen_sync_entries where run_id=(current_setting('test.ka.second_run')::jsonb->>'runId')::bigint),2,'Wiederholung zählt nicht doppelt');
select throws_ok($$select pg_temp.ka_page(current_setting('test.ka.second_claim'),'page:1',null,'[]')$$,'40001',null,'Abweichende Wiederholung wird nicht übernommen');
select throws_ok($$select pg_temp.ka_finish(current_setting('test.ka.second_claim'),'124')$$,'42501',null,'Kontowechsel vor Finish abgelehnt');
select set_config('test.ka.second_finish',pg_temp.ka_finish(current_setting('test.ka.second_claim'))::text,true);
select is(current_setting('test.ka.second_finish')::jsonb->>'state','confirmed','Vollständiger Abgleich atomar abschließbar');
select is(pg_temp.ka_finish(current_setting('test.ka.second_claim')),current_setting('test.ka.second_finish')::jsonb,'Wiederholter Abschluss liefert denselben bestätigten Stand');
reset role;
select is((select count(*)::int from public.kleinanzeigen_publications where available),2,'Vollständiger neuer Bestand umfasst A/B');
select is((select available from public.kleinanzeigen_publications where external_id='103'),false,'Fehlendes C wird nicht verfügbar, nicht verkauft');
select is((select state from public.kleinanzeigen_publications where external_id='103'),'active','Fehlen erfindet keinen Verkaufsstatus');
select is((select count(*)::int from public.kleinanzeigen_publications where published_at is not null),0,'Fehlendes Veröffentlichungsdatum bleibt unbekannt');
select is((select quota_used from public.kleinanzeigen_connections where id=pg_temp.ka_connection()),null::integer,'Fehlender offizieller Zähler wird nicht aus Inseraten berechnet');
set local role service_role;
select throws_ok($$select pg_temp.ka_finish(current_setting('test.ka.first_claim'))$$,'55000',null,'Alter fehlgeschlagener Lauf überschreibt neuen Bestand nicht');
select lives_ok($$select pg_temp.ka_finish(current_setting('test.ka.second_claim'))$$,'Erneutes Finish desselben bestätigten Laufs löst keinen neuen Import aus');
reset role;
set local role authenticated;
select throws_ok($$select * from public.kleinanzeigen_sync_entries$$,'42501',null,'Nutzer liest keine unbestätigten Seiten');
select throws_ok($$update public.kleinanzeigen_publications set available=false$$,'42501',null,'Lesekopie nicht durch Nutzer veränderbar');
select set_config('test.ka.third_run',pg_temp.ka_request()::text,true);
reset role;
set local role service_role;
select set_config('test.ka.third_claim',pg_temp.ka_claim(current_setting('test.ka.third_run'))::text,true);
select throws_ok($$select pg_temp.ka_page(current_setting('test.ka.third_claim'),'page:2',null,'[]')$$,'55000',null,'Fehlende erste Seite verhindert Übernahme');
select throws_ok($$select pg_temp.ka_page(current_setting('test.ka.third_claim'),'page:1','page:3',current_setting('test.ka.page')::jsonb)$$,'22023',null,'Sprung über eine Seite abgelehnt');
select throws_ok($$select pg_temp.ka_page(current_setting('test.ka.third_claim'),'page:1','page:2','[]')$$,'22023',null,'Leere nicht letzte Seite ist kein gültiger Bestand');
select throws_ok($$select pg_temp.ka_page(current_setting('test.ka.third_claim'),'page:1',null,jsonb_build_array(current_setting('test.ka.page')::jsonb->0,current_setting('test.ka.page')::jsonb->0))$$,'40001',null,'Doppelte Anzeigenkennung in einer Seite abgelehnt');
select is((select count(*)::integer from public.kleinanzeigen_sync_entries where run_id=(current_setting('test.ka.third_run')::jsonb->>'runId')::bigint),0,'Fehlerhafte Seite hinterlässt keine teilweise Vormerkung');
select throws_ok(format('select pg_temp.ka_page(current_setting(''test.ka.third_claim''),''page:1'',null,%L::jsonb)',jsonb_build_array((current_setting('test.ka.page')::jsonb->0)||change)::text),'22023',null,'Unbelegtes Anzeigenfeld abgelehnt')
from (values ('{"url":"https://foreign.example/101"}'::jsonb),('{"publishedAt":"2026-10-01T00:00:00Z"}'::jsonb),('{"state":"sold"}'::jsonb),('{"externalId":101}'::jsonb),('{"secret":"private"}'::jsonb)) invalid(change);
select lives_ok($$select pg_temp.ka_page(current_setting('test.ka.third_claim'),'page:1',null,'[]')$$,'Identitätsgeprüfter leerer Bestand kann vorgemerkt werden');
reset role;
set local role authenticated;
select public.kleinanzeigen_disconnect_account('49100000-0000-4000-8000-000000000011',pg_temp.ka_connection());
reset role;
set local role service_role;
select throws_ok($$select pg_temp.ka_finish(current_setting('test.ka.third_claim'))$$,'42501',null,'Widerruf nach letzter Seite blockiert Abschluss');
reset role;
select is((select count(*)::int from public.kleinanzeigen_publications where available),2,'Widerruf bewahrt letzten vollständigen Bestand');
select ok(not has_function_privilege('authenticated','public.kleinanzeigen_finish_sync(uuid,bigint,text,bigint,bigint,text,text,jsonb)','execute'),'Installations-Finish nicht für normale Nutzer aufrufbar');
select * from finish();
rollback;
